// PDF Atelier service worker (web only; Electron never registers it).
// - App shell: precached from sw-manifest.json (generated by vite.config.ts at build time).
// - /pdfjs/* and /tts/*: cache-first on first use (large wasm; not precached).
// - Navigations: network-first, falling back to the cached index.html (offline).
const SHELL = 'shell-'
const RUNTIME = 'runtime-v1'

const manifest = () => fetch('./sw-manifest.json', { cache: 'no-store' }).then((r) => r.json())

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const { version, files } = await manifest()
      await (await caches.open(SHELL + version)).addAll(files)
      await self.skipWaiting()
    })(),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      try {
        const { version } = await manifest()
        for (const key of await caches.keys())
          if (key.startsWith(SHELL) && key !== SHELL + version) await caches.delete(key)
      } catch {
        // Offline while activating: keep old shells, cleaned up on the next online activation.
      }
      await self.clients.claim()
    })(),
  )
})

self.addEventListener('fetch', (event) => {
  const req = event.request
  const url = new URL(req.url)
  if (req.method !== 'GET' || url.origin !== location.origin) return // e.g. Piper models from Hugging Face
  const scope = new URL(self.registration.scope).pathname
  const path = url.pathname.slice(scope.length)

  if (req.mode === 'navigate') {
    event.respondWith(
      fetch(req).catch(async () => (await caches.match('./index.html')) ?? Response.error()),
    )
    return
  }
  if (path === 'sw-manifest.json') return
  if (path.startsWith('pdfjs/') || path.startsWith('tts/')) {
    event.respondWith(
      (async () => {
        const cached = await caches.match(req)
        if (cached) return cached
        const res = await fetch(req)
        if (res.ok) await (await caches.open(RUNTIME)).put(req, res.clone())
        return res
      })(),
    )
    return
  }
  // Hashed build assets and static files: cache-first.
  event.respondWith((async () => (await caches.match(req)) ?? fetch(req))())
})
